// Re-vendor three.js as classic (non-module) scripts so index.html works when
// opened straight from disk (file://) with no server, no CDN and no build step.
//
// Chrome refuses ES modules on file://, so the ES-module builds are wrapped:
//   three.core.js + three.module.js  ->  three.js        (defines window.THREE)
//   examples/jsm/controls/OrbitControls.js -> OrbitControls.js (THREE.OrbitControls)
//
// This script is only for updating the vendored copies. It is not part of running
// the planner. Usage (needs node 18+ and network):
//   node scripts/vendor/revendor.mjs [version]

import { writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const version = process.argv[2] || "0.186.0";
const base = `https://cdn.jsdelivr.net/npm/three@${version}/`;
const here = dirname(fileURLToPath(import.meta.url));

async function get(path) {
	const r = await fetch(base + path);
	if (!r.ok) throw new Error(`${r.status} for ${path}`);
	return await r.text();
}

// Parse `export { a, b, c };` or `export { a, b } from './x.js';` (three uses no renames).
// Returns { names, reexport } where reexport is true for the `from` form.
function exportNames(line) {
	const m = line.match(/^export \{([^}]*)\}(\s+from\s+'[^']*')?;?\s*$/);
	if (!m) throw new Error("unexpected export line: " + line.slice(0, 80));
	return { names: m[1].split(",").map(s => s.trim()).filter(Boolean), reexport: !!m[2] };
}
function importNames(text) {
	const m = text.match(/^import \{([^}]*)\} from '[^']*';/m);
	if (!m) throw new Error("no import block found");
	return m[1].split(",").map(s => s.trim()).filter(Boolean);
}

const core = await get("build/three.core.js");
const mod = await get("build/three.module.js");
const orbit = await get("examples/jsm/controls/OrbitControls.js");
const license = await get("LICENSE");

// --- three.js -------------------------------------------------------------
const coreLines = core.split("\n");
const coreExportIdx = coreLines.findIndex(l => l.startsWith("export {"));
const coreExports = exportNames(coreLines[coreExportIdx]).names;
coreLines.splice(coreExportIdx, 1);

const modLines = mod.split("\n");
const modImportIdx = modLines.findIndex(l => l.startsWith("import {"));
const modImports = importNames(modLines[modImportIdx]);
const modExportIdxs = modLines.map((l, i) => l.startsWith("export {") ? i : -1).filter(i => i >= 0);
// Re-exports from three.core.js are read off __core; the module's own exports are in scope.
const modExports = modExportIdxs.flatMap(i => {
	const e = exportNames(modLines[i]);
	return e.names.map(n => e.reexport ? `${n}: __core.${n}` : n);
});
for (const i of modExportIdxs.slice().reverse()) modLines.splice(i, 1);
modLines.splice(modImportIdx, 1);

const header = `/*
 * three.js r${version} as a classic script (window.THREE) for offline, file:// use.
 * Generated by scripts/vendor/revendor.mjs from build/three.core.js + build/three.module.js.
 * Do not edit by hand.
 *
 * @license
 * Copyright 2010-2026 Three.js Authors
 * SPDX-License-Identifier: MIT
 */
`;
const threeJs =
	header +
	`window.THREE = (function () {\n"use strict";\n` +
	`const __core = (function () {\n"use strict";\n` + coreLines.join("\n") + `\nreturn { ${coreExports.join(", ")} };\n})();\n` +
	`const { ${modImports.join(", ")} } = __core;\n` +
	modLines.join("\n") +
	`\nreturn { ${modExports.join(", ")} };\n})();\n`;
writeFileSync(join(here, "three.js"), threeJs);

// --- OrbitControls.js -----------------------------------------------------
const orbitImports = importNames(orbit);
let orbitBody = orbit.replace(/^import \{[^}]*\} from '[^']*';/m, "");
orbitBody = orbitBody.replace(/^export \{ OrbitControls \};?\s*$/m, "THREE.OrbitControls = OrbitControls;");
const orbitJs =
	`/*
 * three.js r${version} examples/jsm/controls/OrbitControls.js as a classic script.
 * Generated by scripts/vendor/revendor.mjs. Do not edit by hand. MIT, see LICENSE.three.
 */
(function () {
"use strict";
const { ${orbitImports.join(", ")} } = THREE;
` + orbitBody + `\n})();\n`;
writeFileSync(join(here, "OrbitControls.js"), orbitJs);
writeFileSync(join(here, "LICENSE.three"), license);
writeFileSync(join(here, "VERSION"), `three@${version}\n`);

console.log(`vendored three@${version}: three.js (${(threeJs.length / 1024 | 0)} KB, ${modExports.length} exports), OrbitControls.js`);
